const cfg=window.EASY_CONFIG||{},token=new URL(location.href).searchParams.get('token'),root=document.querySelector('#order-content'),message=document.querySelector('#order-message');
const statusText={new:'Шинэ · баталгаажуулалт хүлээж байна',confirmed:'Баталгаажсан',on_way:'Ажилтан очиж байна',done:'Хийгдсэн',cancelled:'Цуцлагдсан'};
const quoteText={pending:'Үнийн санал хүлээж байна',offered:'Таны хариуг хүлээж байна',accepted:'Та үнийг зөвшөөрсөн',declined:'Та үнийн саналаас татгалзсан'};
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
let db;
document.querySelector('#copy-order-link').onclick=async e=>{try{await navigator.clipboard.writeText(location.href);e.currentTarget.textContent='Хуулагдлаа ✓'}catch{e.currentTarget.textContent='Хуулах боломжгүй байна'}};
async function refresh(){if(!db||!token)return;const {data,error}=await db.rpc('customer_booking',{p_token:token});if(error||!data){message.textContent='Захиалга олдсонгүй. Холбоосоо шалгана уу.';return}message.textContent='Захиалга энэ төхөөрөмжид хадгалагдлаа. Үнийн санал болон мессеж энд шинэчлэгдэнэ.';const b=data.booking;window.EASY_SAVED_ORDERS?.save({token,date:b.booking_date,hour:b.booking_hour,vehicle:b.vehicle_model});root.replaceChildren();const info=el('section','detail-section');info.append(el('h3','',`${b.booking_date} · ${String(b.booking_hour).padStart(2,'0')}:00`),el('p','',`${b.vehicle_model} · ${b.plate}`),el('p','',b.address),el('p','',statusText[b.status]||b.status));root.append(info);const quote=el('section','detail-section');quote.append(el('h3','', 'Үнийн санал'),el('p','',b.quote_amount==null?'Үнэ очиж үзсэний дараа тохирно':`${Number(b.quote_amount).toLocaleString('en-US')}₮`),el('p','',quoteText[b.quote_status]||''));if(b.quote_status==='offered'){const actions=el('div','actions');for(const [accept,label] of [[true,'Зөвшөөрөх'],[false,'Татгалзах']]){const button=el('button','',label);button.onclick=async()=>{button.disabled=true;const {error:e}=await db.rpc('respond_quote',{p_token:token,p_accept:accept});if(e)alert('Хариу хадгалагдсангүй.');refresh()};actions.append(button)}quote.append(actions)}root.append(quote);const chat=el('section','detail-section');chat.append(el('h3','', 'Мессеж'));const messages=el('div','messages');for(const m of data.messages||[]){const item=el('div',`bubble ${m.sender}`);item.append(el('small','',m.sender==='admin'?'EASY CAR WASH':'Та'),el('span','',m.body));messages.append(item)}if(!(data.messages||[]).length)messages.append(el('p','', 'Мессеж алга.'));chat.append(messages);const form=el('form','inline');const input=el('input');input.required=true;input.maxLength=1000;input.placeholder='Асуух зүйлээ бичнэ үү';const send=el('button','primary','Илгээх');form.append(input,send);form.onsubmit=async e=>{e.preventDefault();send.disabled=true;const {error:e2}=await db.rpc('customer_message',{p_token:token,p_body:input.value});send.disabled=false;if(e2)alert('Мессеж илгээгдсэнгүй.');else refresh()};chat.append(form);root.append(chat)}
if(!token)message.textContent='Захиалгын холбоос дутуу байна.';else if(!cfg.supabaseUrl||!cfg.supabaseAnonKey)message.textContent='Захиалгын систем холбогдоогүй байна.';else{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');db=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);refresh();setInterval(refresh,20000)}
